use axum::{
    extract::{Extension, Path, State},
    http::StatusCode,
    Json,
};
use serde::{Deserialize, Serialize};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::{
    app_state::AppState,
    auth::{ApiKeySummary, Principal},
};

#[derive(Debug, Serialize)]
pub struct KeyListResponse {
    pub tokens: Vec<ApiKeySummary>,
}

#[derive(Debug, Deserialize)]
pub struct CreateKeyRequest {
    pub id: Option<String>,
    pub namespace: String,
    pub scopes: Vec<String>,
    pub application_id: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct CreateKeyResponse {
    pub secret: String,
    pub id: String,
}

pub async fn list_keys(
    State(state): State<AppState>,
) -> Result<Json<KeyListResponse>, (StatusCode, String)> {
    let tokens = state
        .keys
        .list()
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e))?;
    Ok(Json(KeyListResponse { tokens }))
}

pub async fn create_key(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(req): Json<CreateKeyRequest>,
) -> Result<(StatusCode, Json<CreateKeyResponse>), (StatusCode, String)> {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let name = req.id.unwrap_or_else(|| format!("key-{}", timestamp));
    let scopes = req.scopes;
    let mut authentication_namespaces = vec![req.namespace];
    if !authentication_namespaces
        .iter()
        .any(|value| value == state.namespace.as_ref())
    {
        authentication_namespaces.push(state.namespace.to_string());
    }
    // Argon2 is intentionally CPU/memory expensive. Running it on the async
    // request worker makes readiness and unrelated control-plane requests
    // unavailable while qualification creates several scoped keys.
    let keys = state.keys.clone();
    let key_scopes = scopes.clone();
    let key = tokio::task::spawn_blocking(move || keys.create(name, key_scopes, authentication_namespaces))
        .await
        .map_err(|error| (StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e))?;

    if let Some(application_id) = req.application_id {
        if let Err(error) = state.tenancy.register_application_service(
            &principal.key_id,
            &key.id,
            &application_id,
            scopes,
        ) {
            let _ = state.keys.revoke(&key.id);
            return Err((StatusCode::FORBIDDEN, error));
        }
    }

    Ok((
        StatusCode::CREATED,
        Json(CreateKeyResponse {
            secret: key.secret,
            id: key.id,
        }),
    ))
}

pub async fn revoke_key(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<StatusCode, (StatusCode, String)> {
    let found = state
        .keys
        .revoke(&id)
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e))?;

    if found {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err((StatusCode::NOT_FOUND, "Key not found".to_string()))
    }
}
